  console.log(`Processing unknown practice result ${index}:`, JSON.stringify(data));

  if (data.success && data.logId && data.queue_id) {
    // SMS result from centralized gateway
    processedItems.push({
      id: data.queue_id,
      type: 'SMS',
      practice_id: data.practice_id || data.practiceId,
      status: 'completed'
    });
  } else if (data.failed_items) {
    // Failed emails (no Gmail credentials)
    data.failed_items.forEach(item => {
      processedItems.push(item);
    });
  }
});

console.log('Collected unknown practice items:', JSON.stringify(processedItems));

return processedItems.length > 0 ? processedItems.map(item => ({ json: item })) : [{ json: { message: 'No items processed' } }];

